import{_ as e,o as a,c as i,a2 as l}from"./chunks/framework.CHeM0PsO.js";const b=JSON.parse('{"title":"06 · 发布与验收","description":"","frontmatter":{},"headers":[],"relativePath":"lab/shuangyu-fries/honey-butter/06-release-review.md","filePath":"lab/shuangyu-fries/honey-butter/06-release-review.md","lastUpdated":1787456457000}'),r={name:"lab/shuangyu-fries/honey-butter/06-release-review.md"};function d(o,t,n,s,h,c){return a(),i("div",null,[...t[0]||(t[0]=[l(`<h1 id="_06-·-发布与验收" tabindex="-1">06 · 发布与验收 <a class="header-anchor" href="#_06-·-发布与验收" aria-label="Permalink to &quot;06 · 发布与验收&quot;">​</a></h1><blockquote><p>本页用于成片关门、发布测试与后续内容决策。</p></blockquote><h2 id="首发文案" tabindex="-1">首发文案 <a class="header-anchor" href="#首发文案" aria-label="Permalink to &quot;首发文案&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先选 A / B / C，再看到答案。</span></span>
<span class="line"><span>蜂蜜黄油味，哪一声最像它？</span></span></code></pre></div><h2 id="评论原则" tabindex="-1">评论原则 <a class="header-anchor" href="#评论原则" aria-label="Permalink to &quot;评论原则&quot;">​</a></h2><ul><li>首发片不伪造用户头像、评论内容、点赞数或消费者评价。</li><li>品牌可以在置顶评论里继续提问：「下一次想听一根、两根还是三根？」</li><li>只有真实评论出现后，才使用平台的「回复评论」功能制作后续片。</li><li>评论区出现「像库存音效」「是不是后配的」时，优先发布声音制作幕后并如实标注素材来源，不争辩。</li></ul><h2 id="续拍机制" tabindex="-1">续拍机制 <a class="header-anchor" href="#续拍机制" aria-label="Permalink to &quot;续拍机制&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">#</th><th>形式</th><th>内容</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>评论回复</td><td>按真实高赞评论要求，调整声音距离感后重新生成或录制一次</td></tr><tr><td style="text-align:right;">2</td><td>声纹加量</td><td>一根、两根、三根同时折断，观众继续选最喜欢的一声</td></tr><tr><td style="text-align:right;">3</td><td>咔嚓采样器</td><td>折断、咬下、落杯、颗粒四种真实声音组成 6–8 秒节拍</td></tr><tr><td style="text-align:right;">4</td><td>声音幕后</td><td>展示 Prompt、候选版本和音轨处理；使用 Foley 时再展示麦克风与真实样品</td></tr></tbody></table><h2 id="a-b-测试" tabindex="-1">A/B 测试 <a class="header-anchor" href="#a-b-测试" aria-label="Permalink to &quot;A/B 测试&quot;">​</a></h2><p>只改变一个变量，其他镜头、声音与投放条件保持一致。</p><table tabindex="0"><thead><tr><th>版本</th><th>变量</th><th>文案 / 处理</th></tr></thead><tbody><tr><td>A</td><td>问口味身份</td><td><strong>哪一声是蜂蜜黄油味？</strong></td></tr><tr><td>B</td><td>问主观偏好</td><td><strong>A、B、C，哪一声最解压？</strong></td></tr><tr><td>C</td><td>答案出现较早</td><td>5.5 秒揭晓「都是」</td></tr><tr><td>D</td><td>答案出现较晚</td><td>remix 后 8.2 秒才揭晓</td></tr></tbody></table><p>优先观察 2 秒停留、6 秒播放、完播、重播与每千次播放评论数。不能只用点赞判断：本片最重要的信号是观众是否真的参与选择，以及是否为了比较而重播。</p><h2 id="内容与合规边界" tabindex="-1">内容与合规边界 <a class="header-anchor" href="#内容与合规边界" aria-label="Permalink to &quot;内容与合规边界&quot;">​</a></h2><ol><li>「蜂蜜黄油味」只作为确认后的口味名出现；在配料表未确认前，不展示蜂巢、蜂蜜罐、真实黄油块，也不表述「真蜂蜜」「真黄油」。</li><li>不使用「最脆」「全网最响」等无法证明的绝对化表述。</li><li>不伪造消费者评论、测评结论、点赞数或平台热度。</li><li>不出现低脂、低卡、无油、0 负担、吃不胖等营养或功效暗示。</li><li>最终包装必须使用蜂蜜黄油味终稿物料，不用番茄味包装改色，不让模型自行设计包装。</li><li>AI 音效不得宣传为「原声实录」或「真实盲测」；实际使用产品 Foley 时保留原始文件和对应记录。</li></ol><h2 id="总验收" tabindex="-1">总验收 <a class="header-anchor" href="#总验收" aria-label="Permalink to &quot;总验收&quot;">​</a></h2><h3 id="创意与节奏" tabindex="-1">创意与节奏 <a class="header-anchor" href="#创意与节奏" aria-label="Permalink to &quot;创意与节奏&quot;">​</a></h3><ul><li>[ ] 9:16 竖屏，成片实长 12.0 秒，重要信息不被平台 UI 遮挡</li><li>[ ] 第一帧同时出现产品口味身份与可理解的问题</li><li>[ ] 0.9 秒进入第一声，4.2 秒内完成 A / B / C 三次测试</li><li>[ ] 三个选项的视觉权重一致，不提前暗示答案</li><li>[ ] 「答案：都是」清楚可读，反转成立且不欺骗观众</li><li>[ ] 落版文案至少清晰保留 1.2 秒，最后一声可自然循环回第一帧</li></ul><h3 id="产品与声音" tabindex="-1">产品与声音 <a class="header-anchor" href="#产品与声音" aria-label="Permalink to &quot;产品与声音&quot;">​</a></h3><ul><li>[ ] A、B、C 使用同一 P0 产品身份，动作和最终声音严格同步</li><li>[ ] 断面与表面符合真实马铃薯条状产品参考，不像面包、威化或挤压膨化棒</li><li>[ ] 全片无蜂蜜滴淋、黄油包裹、油光与无依据真实原料暗示</li><li>[ ] 包装只使用客户确认的蜂蜜黄油味终稿物料</li><li>[ ] 音效 Prompt / 原始录音、处理轨、波形来源与最终采用画面可追溯</li></ul><h3 id="发布与合规" tabindex="-1">发布与合规 <a class="header-anchor" href="#发布与合规" aria-label="Permalink to &quot;发布与合规&quot;">​</a></h3><ul><li>[ ] 不伪造评论、评分、销量、点赞或消费者证言</li><li>[ ] 无绝对化、营养功效或未经证实的原料表述</li><li>[ ] 取得所需包装、字体、音乐与人物生成参考的使用授权</li><li>[ ] 主版、投放版、封面和发布文案中的品牌与口味信息一致</li><li>[ ] 后续回复片只引用真实出现的评论</li></ul><h2 id="形式依据" tabindex="-1">形式依据 <a class="header-anchor" href="#形式依据" aria-label="Permalink to &quot;形式依据&quot;">​</a></h2><ul><li><a href="https://ads.tiktok.com/business/creativecenter/quicktok/online/creative-tips-for-food-and-Beverage/pc/en" target="_blank" rel="noreferrer">TikTok Food &amp; Beverage Creative Tips</a>：食品内容强调声音开启、问题式钩子、评论回复与原生互动。</li><li><a href="https://ads.tiktok.com/business/en/next?tt4b_lang_redirect=1" target="_blank" rel="noreferrer">TikTok Next 2026</a>：平台将真实过程、评论反应与社区共同创作视为重要内容方向。</li><li><a href="https://ads.tiktok.com/business/creativecenter/inspiration/topads/pc/en" target="_blank" rel="noreferrer">TikTok Top Ads</a>：成片发布后可按行业与目标对照高表现广告，并结合逐秒互动曲线继续调整答案时点。</li></ul><hr><p><strong>上一步</strong> ← <a href="./05-sound-edit">05 · 声音与剪辑</a> ｜ <strong>返回</strong> → <a href="./">项目总览</a></p>`,25)])])}const p=e(r,[["render",d]]);export{b as __pageData,p as default};
